package org.example.helptreeservice.entity;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.example.helptreeservice.enums.ImagePurpose;
import org.example.helptreeservice.enums.ImageStatus;

import java.time.LocalDateTime;

/**
 * Ownership record for one object in the Silo bucket.
 *
 * <p>The object key is generated by the server only. A client submit never
 * chooses the key or the public URL, so a request cannot overwrite an object
 * owned by another user.</p>
 */
@Entity
@Table(name = "image_objects")
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ImageObject {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "owner_id", nullable = false)
    private Long ownerId;

    @Column(name = "object_key", nullable = false, unique = true, length = 255)
    private String objectKey;

    @Column(nullable = false, columnDefinition = "TEXT")
    private String url;

    @Column(name = "content_type", nullable = false, length = 100)
    private String contentType;

    @Column(name = "size_bytes", nullable = false)
    private Long sizeBytes;

    private Integer width;

    private Integer height;

    @Column(length = 64)
    private String sha256;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private ImagePurpose purpose;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private ImageStatus status;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    @Column(name = "deleted_at")
    private LocalDateTime deletedAt;

    @PrePersist
    protected void onCreate() {
        if (createdAt == null) {
            createdAt = LocalDateTime.now();
        }
        if (sizeBytes == null) {
            sizeBytes = 0L;
        }
        if (purpose == null) {
            purpose = ImagePurpose.GENERAL;
        }
        if (status == null) {
            status = ImageStatus.ACTIVE;
        }
    }
}
